package com.medibook.service;
import com.medibook.dto.AuthDtos.*; import com.medibook.entity.*; import com.medibook.repository.*; import com.medibook.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus;
@Service public class AuthService {
 private final UserRepository users;private final PatientProfileRepository patients;private final PasswordEncoder encoder;private final JwtService jwt;
 public AuthService(UserRepository users,PatientProfileRepository patients,PasswordEncoder encoder,JwtService jwt){this.users=users;this.patients=patients;this.encoder=encoder;this.jwt=jwt;}
 @Transactional public AuthResponse register(Register r){if(users.findByEmail(r.email().toLowerCase().trim()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");Role role;try{role=Role.valueOf(r.role().toUpperCase());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid role");}if(role!=Role.PATIENT)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Self-registration is available for patients only");AppUser u=users.save(new AppUser(r.email(),encoder.encode(r.password()),r.fullName().trim(),role));patients.save(new PatientProfile(u));return response(u);}
 public AuthResponse login(Login r){AppUser u=users.findByEmail(r.email().toLowerCase().trim()).filter(AppUser::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return response(u);}
 private AuthResponse response(AppUser u){return new AuthResponse(jwt.create(u),u.getId(),u.getFullName(),u.getEmail(),u.getRole().name());}
}
